mapper.update:
UPDATE CM_WIDGET_DATASET
   SET DATASET_NAME = #{datasetName}
     , DATASET_TY = #{datasetTy}
     , CONFIG_JSON = CAST(#{configJson} AS JSON)
     , USE_FL = #{useFl}
     , UPDATE_ID = #{updateId}
     , UPDATE_DT = NOW()
WHERE DATASET_ID = #{datasetId}
  AND CMPNY_CD = #{cmpnyCd}

